/bin/bash -lc "python3 - <<'PY'
import urllib.request
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.parts=[]; self.skip=0
 def handle_starttag(self, tag, attrs):
  if tag in ('script','style'): self.skip+=1
 def handle_endtag(self, tag):
  if tag in ('script','style') and self.skip: self.skip-=1
 def handle_data(self, s):
  if not self.skip: self.parts.append(s)
p=P(); p.feed(urllib.request.urlopen('https://react.dev/reference/react/ViewTransition').read().decode()); s=' '.join(' '.join(p.parts).split())
for term in ['::view-transition-old(.', 'enter=\"', 'share=\"', 'update=\"']:
 i=s.find(term)
 print('\\nTERM', term, i, '\\n', s[max(0,i-500):i+800])
PY"

